package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class RoadClipInstrumentation extends Instrumentation {
 void ok(boolean value,String message){if(!value)throw new AssertionError(message);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  File dir=getTargetContext().getFilesDir();byte[] table=Files.readAllBytes(new File(dir,"road-reciprocal.bin").toPath());NativeRoadAttributes normal=new NativeRoadAttributes(ByteBuffer.wrap(table));ByteBuffer.wrap(table).order(ByteOrder.LITTLE_ENDIAN).putInt(64*4,0);NativeRoadAttributes missing=new NativeRoadAttributes(ByteBuffer.wrap(table));NativeRoadAttributes[] tables={normal,missing};int count,accepted=0,rejected=0,empty=0,vertices=0;double maxPosition=0,maxUV=0;
  try(DataInputStream in=new DataInputStream(new FileInputStream(new File(dir,"road-clip.bin")))){ok(in.readInt()==0x3143504e,"Header");count=in.readInt();ok(count>0&&count<100000,"Case count");for(int c=0;c<count;c++){int flag=in.readInt(),n=in.readInt();ok(flag>=0&&flag<2&&n>=3&&n<=32,"Case dimensions");byte[] raw=new byte[288];in.readFully(raw);byte[] before=raw.clone();double[][] points=new double[n][3],copy=new double[n][3];for(int i=0;i<n;i++)for(int k=0;k<3;k++)copy[i][k]=points[i][k]=in.readDouble();boolean expected=in.readInt()!=0;int amount=in.readInt();double[][] reference=new double[amount][5];for(int i=0;i<amount;i++)for(int k=0;k<5;k++)reference[i][k]=in.readDouble();double[][] actual=null;boolean good=true;try{actual=NativeRoadClip.clip(points,ByteBuffer.wrap(raw),tables[flag]);}catch(IllegalArgumentException invalid){good=false;}ok(good==expected,"Acceptance "+c);ok(Arrays.equals(raw,before)&&Arrays.deepEquals(points,copy),"Input mutation "+c);if(good){accepted++;ok(actual.length==amount,"Ring size "+c);vertices+=amount;if(amount==0)empty++;for(int i=0;i<amount;i++)for(int k=0;k<5;k++){double error=Math.abs(actual[i][k]-reference[i][k]);ok(Double.isFinite(error)&&error<=1e-12*Math.max(1,Math.abs(reference[i][k])),"Coordinate "+c);if(k<3)maxPosition=Math.max(maxPosition,error);else maxUV=Math.max(maxUV,error);}}else rejected++;}ok(in.read()==-1,"Trailing cases");}
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_CORRECTED_ROAD_RING");report.put("cases",count);report.put("accepted",accepted);report.put("rejected",rejected);report.put("empty_accepted",empty);report.put("ring_vertices",vertices);report.put("max_position_difference",maxPosition);report.put("max_uv_difference",maxUV);report.put("api",Build.VERSION.SDK_INT);report.put("input_immutable",true);report.put("game_steps",0);report.put("gpu_integration",false);try(FileOutputStream out=getTargetContext().openFileOutput("road-clip-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){android.util.Log.e("NFSUGRoadClip","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}}
}
